changeSet.sql:
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_purpose CHECK (purpose = 'RESEARCH_PARTICIPATION');
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_schema CHECK (schema_name = 'hephaestus.research-dataset' AND schema_version > 0);
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_window CHECK (window_from < window_to AND window_to <= cutoff_at + interval '1 day');
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_hash CHECK (content_sha256 ~ '^[0-9a-f]{64}$');
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_counts CHECK (participant_count >= 0 AND result_count >= 0 AND problem_count >= 0 AND feedback_count >= 0 AND feedback_excluded_count >= 0);
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_use CHECK (use_until > created_at);
ALTER TABLE research_disclosure ADD CONSTRAINT ck_research_disclosure_closure CHECK ((closed_at IS NULL) = (closure IS NULL) AND (closure IS NULL OR closure IN ('DESTROYED','ANONYMIZED')));
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_key CHECK (participant_key ~ '^p_[a-z2-7]{26}$');
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_reason CHECK ((removal_required_at IS NULL) = (removal_reason IS NULL) AND (removal_reason IS NULL OR removal_reason IN ('CONSENT_WITHDRAWN','CONSENT_SUPERSEDED','QUESTION_CHANGED','ACCOUNT_ERASED')));
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_removed CHECK (removed_at IS NULL OR removal_required_at IS NOT NULL);
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_link CHECK (account_id IS NOT NULL OR removal_reason IS NOT NULL);
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_pruned CHECK (removed_at IS NULL OR (account_id IS NULL AND grant_decision_id IS NULL));
ALTER TABLE research_disclosure_subject ADD CONSTRAINT ck_research_disclosure_subject_grant CHECK (grant_decision_id IS NOT NULL OR removed_at IS NOT NULL);

rollback.sql:
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_grant;
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_pruned;
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_link;
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_removed;
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_reason;
ALTER TABLE research_disclosure_subject DROP CONSTRAINT ck_research_disclosure_subject_key;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_closure;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_use;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_counts;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_hash;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_window;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_schema;
ALTER TABLE research_disclosure DROP CONSTRAINT ck_research_disclosure_purpose;

DO $research_audit_rollback$
BEGIN
    IF EXISTS (SELECT 1 FROM auth_event WHERE event_type IN ('RESEARCH_DATASET_RELEASED','RESEARCH_REMOVAL_RECORDED')) THEN
        RAISE EXCEPTION 'Research audit rows exist; retain the widened audit constraint';
    END IF;
    ALTER TABLE auth_event DROP CONSTRAINT ck_auth_event_event_type;
    ALTER TABLE auth_event ADD CONSTRAINT ck_auth_event_event_type CHECK (event_type IN ('USER_VIEW', 'LOGIN', 'PASSKEY_CHANGED', 'PASSKEY_VERIFIED', 'LOGIN_FAILED', 'LOGOUT', 'TOKEN_REFRESH', 'JWT_REVOKED', 'IDENTITY_LINKED', 'IDENTITY_UNLINKED', 'IMPERSONATION_BEGIN', 'IMPERSONATION_END', 'ACCOUNT_DELETED', 'EXPORT_REQUESTED', 'PERSON_DATA_PREVIEWED', 'PERSON_DATA_EXPORTED', 'PERSON_DATA_ERASURE_REQUESTED', 'APP_ROLE_CHANGED', 'RESEARCH_CONSENT_REVOKED', 'WORKSPACE_ELEVATION', 'LLM_CONNECTION_CREATED', 'LLM_CONNECTION_UPDATED', 'LLM_CONNECTION_DELETED', 'LLM_MODEL_CREATED', 'LLM_MODEL_UPDATED', 'LLM_MODEL_DELETED', 'LLM_MODEL_PRICE_CHANGED', 'LLM_MODEL_SHARING_CHANGED', 'LLM_SETTINGS_CHANGED', 'LOGIN_PROVIDER_CREATED', 'LOGIN_PROVIDER_UPDATED', 'LOGIN_PROVIDER_DELETED', 'SILENT_MODE_CHANGED', 'PUBLIC_ACTIVITY_CHANGED'));
END
$research_audit_rollback$;
